create table if not exists public.campaign_verification_requirements (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete cascade,task_id uuid not null references public.tasks(id) on delete cascade,verification_mode text not null check (verification_mode in ('automatic','screenshot','automatic_screenshot')),requirements jsonb not null default '{}'::jsonb,status text not null default 'pending' check (status in ('pending','active','completed','blocked')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(campaign_id,task_id));
alter table public.campaign_verification_requirements enable row level security;
create index if not exists campaign_verification_requirements_campaign_idx on public.campaign_verification_requirements(campaign_id);
create index if not exists campaign_verification_requirements_task_idx on public.campaign_verification_requirements(task_id);